+	if got := findWPConfig(htmlData, site); got != filepath.Join(site, "wp-config.php") {
+		t.Errorf("docroot config should win: got %s", got)
+	}
+	os.Remove(filepath.Join(site, "wp-config.php"))
+	write(filepath.Join(domain, "wp-settings.php"))
